def-hyp[predicate](
    Type.annotation(@A, Set(T@Set.ctxt.T)),
    Topology.compact(A),
    Logic.forall-typed(
        @C,
        Set(Set(T@Set.ctxt.T)),
        Logic.implies(
            Topology.openCover(C, A),
            Logic.exists-typed(
                @F,
                Set(Set(T@Set.ctxt.T)),
                Logic.and(Set.subset(F, C), Logic.and(Topology.openCover(F, A), Set.finite(F)))
            )
        )
    )
)
